import sys
import sqlite3
import json
import argparse
from functools import reduce

def compute_code_check(token_code):
    return reduce(lambda acc, c: (acc * 31 + ord(c)) % 1000000, token_code, 0)

def process_request(db_path, token_data):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    token_id = token_data['token_id']
    token_code = token_data['token_code']
    cost = token_data['cost']
    filters = token_data.get('filters', {})

    # Check token existence, enabled status, and code check
    cursor.execute("SELECT code_check, credits, enabled FROM tokens WHERE token_id = ?", (token_id,))
    token_row = cursor.fetchone()

    if not token_row or token_row[2] == 0:
        return {"status": "denied"}

    computed_code_check = compute_code_check(token_code)
    if computed_code_check != token_row[0]:
        return {"status": "denied"}

    if token_row[1] < cost:
        return {"status": "denied"}

    # Update credits
    cursor.execute("UPDATE tokens SET credits = credits - ? WHERE token_id = ?", (cost, token_id))
    conn.commit()

    # Prepare filters for item lookup
    filter_conditions = []
    for key, value in filters.items():
        if key == 'id':
            filter_conditions.append(f"items.id = ?")
            filter_values.append(value)
        elif key == 'title':
            filter_conditions.append(f"items.title = ?")
            filter_values.append(value)
        elif key == 'price':
            filter_conditions.append(f"items.price = ?")
            filter_values.append(value)
        elif key == 'category':
            filter_conditions.append(f"items.category = ?")
            filter_values.append(value)
        elif key == 'status':
            filter_conditions.append(f"items.status = ?")
            filter_values.append(value)

    filter_values = []
    if filter_conditions:
        query = f"SELECT id, title, price, category, status FROM items WHERE {', '.join(filter_conditions)} ORDER BY id ASC"
        cursor.execute(query, filter_values)
    else:
        cursor.execute("SELECT id, title, price, category, status FROM items ORDER BY id ASC")

    rows = cursor.fetchall()
    conn.close()

    return {"status": "ok", "rows": [dict(zip(['id', 'title', 'price', 'category', 'status'], row)) for row in rows]}

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--db', required=True, help='Path to SQLite database file')
    args = parser.parse_args()

    for line in sys.stdin:
        try:
            token_data = json.loads(line.strip())
            result = process_request(args.db, token_data)
            print(json.dumps(result))
        except json.JSONDecodeError:
            continue

if __name__ == "__main__":
    main()
